export async function POST(request) {
  const body = await request.json();
  if (!body.name) {
    return NextResponse.json({ error: 'name is required' }, { status: 400 });
  }
  const product = { id: 1, name: body.name };
  return NextResponse.json(product, { status: 201 });
}

